class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + x
        ans = float('inf')
        for i in range(n):
            for L in range(l, r + 1):
                j = i + L
                if j > n:
                    break
                s = pre[j] - pre[i]
                if s > 0:
                    ans = min(ans, s)
        return ans if ans < float('inf') else -1

